mapper.select:
SELECT 1 - (refund_cnt + no_show_cnt) / NULLIF(total_cnt, 0)
FROM (
    SELECT
        (SELECT COUNT(1) FROM TR_OUTP_FIN_CLINIC_MASTER c
            INNER JOIN TR_DEPT_DICT d ON c.dept_code = d.dept_code
            WHERE c.stat_date BETWEEN #{startDate} AND #{endDate}
            ) AS total_cnt,
        (SELECT COUNT(1) FROM TR_OUTP_FIN_CLINIC_MASTER c
            INNER JOIN TR_DEPT_DICT d ON c.dept_code = d.dept_code
            WHERE c.stat_date BETWEEN #{startDate} AND #{endDate}
              AND c.returned_date IS NOT NULL
            ) AS refund_cnt,
        (SELECT COUNT(1) FROM (
            SELECT dd, k FROM (
                SELECT TRUNC(q.stat_date) AS dd, NVL(TO_CHAR(q.id_no), 'Q' || q.visit_no) AS k
                FROM TR_OUTP_FIN_MOP_QUEUE q
                LEFT JOIN TR_OUTP_FIN_CLINIC_MASTER cm
                  ON cm.patient_id = q.patient_id AND cm.queue_num = q.queue_num
                WHERE q.appoints_indicator = 1
                  AND q.stat_date BETWEEN #{startDate} AND #{endDate}
                  AND cm.patient_id IS NULL
            ) GROUP BY dd, k
            UNION ALL
            SELECT dd, k FROM (
                SELECT TRUNC(c2.stat_date) AS dd, NVL(c2.id_no, 'V' || c2.visit_no) AS k
                FROM TR_OUTP_FIN_CLINIC_MASTER c2
                INNER JOIN TR_DEPT_DICT d ON c2.dept_code = d.dept_code
                WHERE c2.registration_status <= 1
                  AND c2.stat_date BETWEEN #{startDate} AND #{endDate}

            ) GROUP BY dd, k
        )) AS no_show_cnt
    FROM DUAL
)

SELECT weather_coef
FROM tr_fc_weather
WHERE weather_date = #{weatherDate}

SELECT hol_type
FROM tr_fc_holiday
WHERE hol_date = #{holDate}
